import{_ as o,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Day Melbourne Promo","description":"","frontmatter":{"title":"Ceph Day Melbourne Promo","date":"2015-11-17T00:00:00.000Z","updated":"2015-11-17T00:00:00.000Z","tags":["Ceph社区","备份存储性能提升","分布式存储","存储 consolidation","Ceph性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/Ceph_Day_Melbourne_Promo.md","filePath":"posts/2015/Ceph_Day_Melbourne_Promo.md","lastUpdated":1780459816000}'),i={name:"posts/2015/Ceph_Day_Melbourne_Promo.md"};function n(p,e,s,a,h,_){return t(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph社区交流与备份存储性能提升探讨</p><p><strong>会议时间</strong>： 2023年11月[具体日期]</p><p><strong>会议地点</strong>： IMATS ft 和 Monash University in Melbourne</p><p><strong>参会人员</strong>：</p><ul><li>Patrick McGarry：Ceph社区总监，负责Ceph上游社区相关事务</li><li>Brad Hubbub：Red Hat支持交付部门员工</li><li>Steve Gwinnett：Monash大学研究部副总监</li></ul><p><strong>会议内容</strong>：</p><ol><li><p><strong>背景介绍</strong>：</p><ul><li>本次会议由Monash大学组织，旨在深入探讨Ceph社区的现状和发展，以及如何提升Ceph备份存储的性能。</li><li>Patrick McGarry介绍了Ceph社区的参与方式和现状，特别强调了社区在邮件列表和故障排除方面的活跃互动。</li></ul></li><li><p><strong>Ceph社区体验</strong>：</p><ul><li>参会者分享了在Ceph社区中的积极体验，普遍认为社区友好且提供了丰富的交流平台和问题解答渠道。</li><li>Steve Gwinnett表示，Ceph社区对新成员非常欢迎，论坛等交流平台有助于参与者互相交流和提问。</li></ul></li><li><p><strong>Monash大学Ceph部署情况</strong>：</p><ul><li>Monash大学正在部署Ceph备份存储，并计划通过Ceph提升存储性能。</li><li>会议讨论了Ceph在存储 consolidation 方面的表现，以及其对多种应用的支持能力。</li></ul></li><li><p><strong>讨论议题</strong>：</p><ul><li>如何进一步提升Ceph备份存储的性能？</li><li>如何加强Ceph社区的互动与合作？</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>Monash大学将继续优化Ceph备份存储的配置，并探索性能提升的方案。</li><li>Ceph社区将加强内部交流，提升社区活跃度，以促进更好的合作。</li></ul></li></ol><p><strong>关键词</strong>： Ceph社区、备份存储性能提升、存储 consolidation、邮件列表、故障排除、Ceph性能、Ceph社区互动、社区参与</p>',9)])])}const d=o(i,[["render",n]]);expo